    Set<V> part1 = new HashSet<>();
    Set<V> part2 = new HashSet<>();

    // Assuming resultMap contains vertices with keys indicating their partition
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("part1")) {
            part1.add(entry.getValue());
        } else if (entry.getKey().startsWith("part2")) {
            part2.add(entry.getValue());
        }
    }

    // Add edges between all vertices in part1 and part2
    for (V vertex1 : part1) {
        for (V vertex2 : part2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

