@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    // Assuming the vertices are already created and stored in resultMap
    // with keys representing partitions, e.g., "left" and "right"

    // Retrieve the vertices for each partition
    List<V> leftVertices = new ArrayList<>(resultMap.values()).subList(0, resultMap.size() / 2);
    List<V> rightVertices = new ArrayList<>(resultMap.values()).subList(resultMap.size() / 2, resultMap.size());

    // Add edges between each vertex in the left partition and each vertex in the right partition
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

