public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = paramType.getActualTypeArguments();

    if (actualTypeArguments == null || actualTypeArguments.length == 0) {
        return null;
    }

    Class<?>[] result = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArg = actualTypeArguments[i];
        if (typeArg instanceof Class<?>) {
            result[i] = (Class<?>) typeArg;
        } else if (typeArg instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArg;
            result[i] = resolveTypeVariable(targetType, typeVariable);
        } else {
            return null; // Cannot resolve the type argument
        }
    }

    return result;
}

private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    Class<?> currentClass = targetType;
    while (currentClass != null) {
        Type genericSuperclass = currentClass.getGenericSuperclass();
        if (genericSuperclass instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
            TypeVariable<?>[] typeParameters = currentClass.getSuperclass().getTypeParameters();
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            for (int i = 0; i < typeParameters.length; i++) {
                if (typeVariable.equals(typeParameters[i])) {
                    if (actualTypeArguments[i] instanceof Class<?>) {
                        return (Class<?>) actualTypeArguments[i];
                    } else if (actualTypeArguments[i] instanceof TypeVariable<?>) {
