private static Type resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    Class<?> declaringClass = (Class<?>) typeVariable.getGenericDeclaration();
    if (declaringClass.equals(targetType)) {
        return typeVariable;
    }

    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
        TypeVariable<?>[] typeParameters = declaringClass.getTypeParameters();
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        for (int i = 0; i < typeParameters.length; i++) {
            if (typeVariable.equals(typeParameters[i])) {
                Type actualTypeArgument = actualTypeArguments[i];
                if (actualTypeArgument instanceof Class<?>) {
                    return actualTypeArgument;
                } else if (actualTypeArgument instanceof TypeVariable<?>) {
                    return resolveTypeVariable((Class<?>) parameterizedType.getRawType(), (TypeVariable<?>) actualTypeArgument);
                } else {
                    return null; // Unsupported type
                }
            }
        }
    }

    for (Type genericInterface : targetType.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            return resolveTypeVariable(targetType, typeVariable);
        }
    }

