private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    if (targetType == null) {
        return null;
    }

    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
        TypeVariable<?>[] typeVariables = targetType.getSuperclass().getTypeParameters();
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        for (int i = 0; i < typeVariables.length; i++) {
            if (typeVariables[i].equals(typeVariable)) {
                Type actualTypeArgument = actualTypeArguments[i];
                if (actualTypeArgument instanceof Class<?>) {
                    return (Class<?>) actualTypeArgument;
                } else if (actualTypeArgument instanceof TypeVariable<?>) {
                    return resolveTypeVariable(targetType.getSuperclass(), (TypeVariable<?>) actualTypeArgument);
                }
            }
        }
    }

    // Check interfaces too
    Type[] genericInterfaces = targetType.getGenericInterfaces();
    for (Type genericInterface : genericInterfaces) {
        if (genericInterface instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericInterface;
            TypeVariable<?>[] typeVariables = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

            for (int i = 0; i < typeVariables.length; i++) {
                if (typeVariables[i].equals(typeVariable)) {
                    Type actualTypeArgument = actualTypeArguments[i];
                    if (actualTypeArgument instanceof Class<?>) {
                        return (Class<?>) actualTypeArgument;
                    } else if (actualTypeArgument instanceof TypeVariable<?>) {
                        return resolveTypeVariable((Class<?>) parameterizedType.getRawType(), (TypeVariable<?>) actualTypeArgument);
                    }
                }
            }
        }
    }

    // If nothing found, try the superclass of the target type
    return resolveTypeVariable(targetType.getSuperclass(), typeVariable);
}

