    int len = str.length();
    if (len == 0) return lb;
    int index = 0;
    byte[] buffer = lb.buffer;
    int bufferLen = lb.limit;
    int i = lb.offset;
    while (index < len) {
        char c = str.charAt(index++);
        if (c < 0x80) {
            if (i == bufferLen) {
                lb.offset = i;
                lb = lb.next;
                buffer = lb.buffer;
                bufferLen = lb.limit;
                i = 0;
            }
            buffer[i++] = (byte) c;
        } else if (c < 0x800) {
            if (i + 2 > bufferLen) {
                lb.offset = i;
                lb = lb.next;
                buffer = lb.buffer;
                bufferLen = lb.limit;
                i = 0;
            }
            buffer[i++] = (byte) (0xC0 | (c >> 6));
            buffer[i++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isSurrogate(c)) {
            char low = str.charAt(index++);
            int codePoint = Character.toCodePoint(c, low);
            if (i + 4 > bufferLen) {
                lb.offset = i;
                lb = lb.next;
                buffer = lb.buffer;
                bufferLen = lb.limit;
                i = 0;
            }
            buffer[i++] = (byte) (0xF0 | (codePoint >> 18));
            buffer[i++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            buffer[i++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer[i++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            if (i + 3 > bufferLen) {
                lb.offset = i;
                lb = lb.next;
                buffer = lb.buffer;
                bufferLen = lb.limit;
                i = 0;
            }
            buffer[i++] = (byte) (0xE0 | (c >> 12));
            buffer[i++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[i++] = (byte) (0x80 | (c & 0x3F));
        }
    }
    lb.offset = i;
    return lb;
}

