        return lb;
    }
    final int len = str.length();
    int size = len * 3;
    if (lb.start + size >= lb.limit) {
        lb = lb.ensureCapacity(size);
    }
    final byte[] data = lb.buffer;
    int i = lb.start;
    for (int j = 0; j < len; j++) {
        final char ch = str.charAt(j);
        if (ch < 0x80) {
            data[i++] = (byte) ch;
        } else if (ch < 0x800) {
            data[i++] = (byte) (0xc0 | (ch >> 6));
            data[i++] = (byte) (0x80 | (ch & 0x3f));
