            data[i++] = (byte) (0xe0 | (ch >> 12));
            data[i++] = (byte) (0x80 | ((ch >> 6) & 0x3f));
            data[i++] = (byte) (0x80 | (ch & 0x3f));
        }
    }
    lb.start = i;
    return lb;
