    Matcher matcher = Pattern.compile("\\$\\{([^}]+)\\}").matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String var = matcher.group(1);
        String subst = props.getProperty(var, "");
        matcher.appendReplacement(sb, Matcher.quoteReplacement(subst));
    }
    matcher.appendTail(sb);
    return sb.toString();
}

