public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= len) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b': sb.append('\b'); break;
                case 't': sb.append('\t'); break;
                case 'n': sb.append('\n'); break;
                case 'f': sb.append('\f'); break;
                case 'r': sb.append('\r'); break;
                case '"': sb.append('\"'); break;
                case '\'': sb.append('\''); break;
                case '\\': sb.append('\\'); break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new Exception("Invalid Unicode escape sequence at index " + i);
                    }
                    int codePoint = Integer.parseInt(str.substring(i + 1, i + 5), 16);
                    sb.append(Character.toChars(codePoint));
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape character '" + c + "' at index " + i);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

