    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Invalid escape sequence");
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    result.append('\b');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '\"':
                    result.append('\"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case 'u':
                    if (i + 5 >= str.length()) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int uni = Integer.parseInt(hex, 16);
                        result.append((char) uni);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence", e);
                    }
                    i += 5;
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
            i += 2;
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

