final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int utf8Length = readUnsignedShort(constantPoolEntryIndex);
    int utf8Offset = constantPoolEntryIndex + 2;
    int charLength = 0;
    int c;
    for (int i = 0; i < utf8Length; i++) {
        c = classFileBuffer[utf8Offset + i] & 0xFF;
        if (c < 0x80) {
            charBuffer[charLength++] = (char) c;
        } else if ((c & 0xE0) == 0xC0) {
            charBuffer[charLength++] = (char) (((c & 0x1F) << 6) | (classFileBuffer[utf8Offset + ++i] & 0x3F));
        } else {
            charBuffer[charLength++] = (char) (((c & 0x0F) << 12) | ((classFileBuffer[utf8Offset + ++i] & 0x3F) << 6) | (classFileBuffer[utf8Offset + ++i] & 0x3F));
        }
    }
    return new String(charBuffer, 0, charLength);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int index = 2 + (constantPoolEntryIndex << 1);
    int length = classFileBuffer[index++] & 0xFF;
    length = (length << 8) | (classFileBuffer[index++] & 0xFF);
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) ((classFileBuffer[index++] & 0xFF) << 8 | (classFileBuffer[index++] & 0xFF));
