    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (!edgeList.isEmpty()) {
        V startVertex = graph.getEdgeSource(edgeList.get(0));
        vertexList.add(startVertex);
        Map<V, E> edgeMap = new HashMap<>();
        for (E edge : edgeList) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            edgeMap.put(source, edge);
            edgeMap.put(target, edge);
        }
        V currentVertex = startVertex;
        while (!edgeList.isEmpty()) {
            E currentEdge = edgeMap.get(currentVertex);
            edgeList.remove(currentEdge);
            V nextVertex = graph.getEdgeSource(currentEdge);
            if (nextVertex.equals(currentVertex)) {
                nextVertex = graph.getEdgeTarget(currentEdge);
            }
            vertexList.add(nextVertex);
            currentVertex = nextVertex;
        }
    }
    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, edgeList, 0);
}

