    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, pathVertices, 0.0);
    }

    // Assuming the graph is connected and the tour is valid
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    pathVertices.add(startVertex);

    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        pathVertices.add(targetVertex);
        startVertex = targetVertex;
    }

    double weight = 0.0;
    for (E edge : edgeList) {
