protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertexPath = new ArrayList<>();
    if (tour.isEmpty()) {
        return new org.jgrapht.graph.SimpleGraphPath<>(graph, vertexPath, 0);
    }

    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    vertexPath.add(startVertex);

    V currentVertex = startVertex;
    while (!tour.isEmpty()) {
        E edge = null;
        for (E e : tour) {
            if (graph.getEdgeSource(e).equals(currentVertex) || graph.getEdgeTarget(e).equals(currentVertex)) {
                edge = e;
                break;
            }
        }
        if (edge == null) {
            throw new IllegalArgumentException("The provided set of edges does not form a valid tour.");
        }
        tour.remove(edge);

        V nextVertex = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
        vertexPath.add(nextVertex);
        currentVertex = nextVertex;
    }

    return new org.jgrapht.graph.SimpleGraphPath<>(graph, vertexPath, 0);
}

